import java.util.*;

public class SccOracle {
  // Reachability via BFS from s.
  static boolean[] reach(int V, int[][] e, int s){
    List<List<Integer>> adj=new ArrayList<>(); for(int i=0;i<V;i++) adj.add(new ArrayList<>());
    for(int[] a:e) adj.get(a[0]).add(a[1]);
    boolean[] r=new boolean[V]; Deque<Integer> st=new ArrayDeque<>(); st.push(s); r[s]=true;
    while(!st.isEmpty()){int u=st.pop(); for(int w:adj.get(u)) if(!r[w]){r[w]=true;st.push(w);}}
    return r;
  }
  // Brute SCC: u,v same iff reach(u,v)&&reach(v,u). Return normalized set of sorted components.
  static Set<List<Integer>> brute(int V,int[][] e){
    boolean[][] R=new boolean[V][]; for(int i=0;i<V;i++) R[i]=reach(V,e,i);
    int[] comp=new int[V]; Arrays.fill(comp,-1); int c=0;
    for(int i=0;i<V;i++){ if(comp[i]!=-1) continue; comp[i]=c;
      for(int j=i+1;j<V;j++) if(comp[j]==-1 && R[i][j] && R[j][i]) comp[j]=c; c++; }
    Map<Integer,List<Integer>> m=new TreeMap<>();
    for(int i=0;i<V;i++) m.computeIfAbsent(comp[i],k->new ArrayList<>()).add(i);
    Set<List<Integer>> s=new HashSet<>();
    for(List<Integer> g:m.values()){ Collections.sort(g); s.add(g); }
    return s;
  }
  public static void main(String[] a){
    Random r=new Random(11); int trials=200000, miss=0, withPar=0;
    for(int t=0;t<trials;t++){
      int V=1+r.nextInt(7); int E=r.nextInt(3*V+1);
      int[][] e=new int[E][2]; Set<String> seen=new HashSet<>(); boolean par=false;
      for(int i=0;i<E;i++){ int u=r.nextInt(V),v=r.nextInt(V); e[i]=new int[]{u,v};
        if(!seen.add(u+">"+v)) par=true; }
      if(par) withPar++;
      List<List<Integer>> got=new StronglyConnectedComponents().find(DirectedGraph.fromEdges(V,e));
      Set<List<Integer>> gs=new HashSet<>(got);
      Set<List<Integer>> bs=brute(V,e);
      if(!gs.equals(bs)){ if(miss++<5) System.out.println("MISMATCH "+Arrays.deepToString(e)+" got "+gs+" exp "+bs); }
    }
    System.out.println("trials="+trials+" withParallelArcs="+withPar+" mismatches="+miss);
  }
}
